import json

with open('output/report_data.json') as f:
    data = json.load(f)
with open('output/charts.json') as f:
    charts = json.load(f)

# Prepare inline values for quick reference
kpis = data['kpis']
meta = data['meta']

# Helper for formatting numbers
def fmt(num, dec=1):
    return f"{num:,.{dec}f}"

# Build HTML
html = f'''<!DOCTYPE html>
