# The simple validator is wrong because it doesn't handle self-closing tags and <img> properly.
# Let's use a real parser.
from html.parser import HTMLParser

class RealValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','!doctype'}
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag.lower() in self.void:
            return
        self.stack.append(tag.lower())
    def handle_endtag(self, tag):
        t = tag.lower()
        if t in self.void:
            return
        if self.stack and self.stack[-1] == t:
            self.stack.pop()
        else:
            # try to find in stack
            if t in self.stack:
                idx = len(self.stack) - 1 - self.stack[::-1].index(t)
                self.stack = self.stack[:idx]
            else:
                self.errors.append(f"Close without open: {t}")

with open('output/final_report.html', 'r', encoding='utf-8') as f:
    html = f.read()

v = RealValidator()
v.feed(html)
print("Unclosed tags:", v.stack)
print("Errors:", v.errors[:10])
print("Valid:", len(v.stack) == 0 and len(v.errors) == 0)
PYEOF
